const HOST = (process.env.LEADSRADAR_AGENT_HOST || "doubao-work").toLowerCase();
// ⭐r90c HTTP 模式开关（提前声明：stdin EOF watchdog 需豁免）——扣子桌面端仅支持 Streamable HTTP；
